diff --git a/apps/hyper/HyperKCore-Efficient.C b/apps/hyper/HyperKCore-Efficient.C
index e6e3582..ce069d7 100644
--- a/apps/hyper/HyperKCore-Efficient.C
+++ b/apps/hyper/HyperKCore-Efficient.C
@@ -3,11 +3,544 @@
 #include "index_map.h"
 #include "bucket.h"
 #include "edgeMapReduce.h"
+#ifdef _OPENMP
+#include <omp.h>
+#endif
+#include <cstring>
+
+// Hypergraph k-core decomposition (core numbers) by level-synchronous peeling.
+//
+// D[v] is the number of alive hyperedges incident to v while v is alive, and
+// v's core number once v has been removed.  Levels k are processed in
+// increasing order.  At level k every alive vertex whose degree is at most k
+// is removed with core number k; removing a vertex deletes each alive
+// hyperedge containing it, and deleting a hyperedge decrements the degree of
+// each of its members, which may remove further vertices at the same level.
+//
+// Large inputs use peel_par: bulk-synchronous rounds without atomics.  Each
+// thread owns a contiguous, 64-aligned range of vertices and of hyperedges.
+// A round
+//   1. turns the current frontier (vertices removed in the previous round)
+//      into deletion requests sent to the owners of their alive hyperedges,
+//      or, when that is cheaper, has every owner scan its alive hyperedges for
+//      a removed member ("dense" round);
+//   2. lets hyperedge owners delete the requested hyperedges in id order and
+//      send one decrement message per member that is still alive;
+//   3. lets vertex owners apply the decrements; vertices whose degree drops to
+//      k form the next frontier.
+// Decrement messages are bucketed by destination sub-range so that applying a
+// bucket only touches a cache-sized slice of D.  With one thread the same
+// scheme runs without synchronisation; it is faster than direct random
+// updates because emitting and applying are tight, independent loops.
+
+namespace hkc {
+
+#ifndef HKC_PF
+#define HKC_PF 8              // software prefetch distance (list entries)
+#endif
+#ifndef HKC_DENSE_RATIO
+#define HKC_DENSE_RATIO 6.0   // dense round if alive incidences < ratio * frontier incidences
+#endif
+#ifndef HKC_BUCKET_V
+#define HKC_BUCKET_V 16384    // target vertices per decrement bucket
+#endif
+#ifndef HKC_PAR_MIN
+#define HKC_PAR_MIN 200000    // below this much work use the simple sequential peel
+#endif
+
+static inline void* xmalloc(size_t n) {
+  void* p = malloc(n ? n : 1);
+  if (!p) { fprintf(stderr, "Cannot allocate space\n"); exit(1); }
+  return p;
+}
+static inline void* xcalloc(size_t n, size_t s) {
+  void* p = calloc(n ? n : 1, s);
+  if (!p) { fprintf(stderr, "Cannot allocate space\n"); exit(1); }
+  return p;
+}
+
+// Compact adjacency: the list of x is adj[off[x] .. off[x+1]).
+struct CSR {
+  const uintE* adj;
+  uintT* off;
+  uintE* owned;   // non-null if adj is a private copy
+};
+
+// ------------------------------------------------------- simple sequential
+// Queue-driven peeling, used for small inputs and builds without OpenMP.
+// Degrees of queued vertices keep counting alive hyperedges, so a queued
+// vertex stops scanning its list once all of its alive hyperedges are found.
+static void peel_seq(size_t nv, size_t nh, const CSR& Vc, const CSR& Hc, uintE* D) {
+  const uintE* vadj = Vc.adj; const uintT* voff = Vc.off;
+  const uintE* hadj = Hc.adj; const uintT* hoff = Hc.off;
+  uint64_t* dead = (uint64_t*)xcalloc(nh / 64 + 2, 8);
+  uintE* vq = (uintE*)xmalloc(sizeof(uintE) * (nv + 1));
+  uintE* eq = (uintE*)xmalloc(sizeof(uintE) * (nh + 1));
+  size_t removed = 0, eh = 0, et = 0;
+  uintE k = 0;
+  bool first = true;
+  while (removed < nv) {
+    // next level: k = min alive degree; queue alive vertices with degree k
+    size_t vh = 0, vt = 0;
+    uintE mn = UINT_E_MAX;
+    for (size_t v = 0; v < nv; v++) {
+      uintE d = D[v];
+      if (!first && d <= k) continue;
+      if (d < mn) { mn = d; vt = 0; }
+      if (d == mn) vq[vt++] = (uintE)v;
+    }
+    k = mn; first = false;
+    const uintE k1 = k + 1;
+    while (vh < vt) {
+      // queued vertices delete their alive hyperedges
+      for (; vh < vt; vh++) {
+        if (vh + 2 * HKC_PF < vt) __builtin_prefetch(voff + vq[vh + 2 * HKC_PF]);
+        if (vh + HKC_PF < vt) __builtin_prefetch(vadj + voff[vq[vh + HKC_PF]]);
+        uintE v = vq[vh];
+        uintE cnt = D[v];   // >= number of alive incident hyperedges
+        if (cnt == 0) continue;
+        const uintE* ve = vadj + voff[v];
+        const uintE* vend = vadj + voff[v + 1];
+        for (; ve < vend; ve++) {
+          uintE e = *ve;
+          uint64_t m = 1ULL << (e & 63);
+          uint64_t w = dead[e >> 6];
+          if (w & m) continue;
+          dead[e >> 6] = w | m;
+          eq[et++] = e;
+          if (--cnt == 0) break;
+        }
+      }
+      // deleted hyperedges decrement their members
+      for (; eh < et; eh++) {
+        if (eh + 2 * HKC_PF < et) __builtin_prefetch(hoff + eq[eh + 2 * HKC_PF]);
+        if (eh + HKC_PF < et) __builtin_prefetch(hadj + hoff[eq[eh + HKC_PF]]);
+        uintE e = eq[eh];
+        const uintE* he = hadj + hoff[e];
+        const uintE* hend = hadj + hoff[e + 1];
+        for (; he < hend; he++) {
+          uintE u = *he;
+          uintE du = D[u];
+          D[u] = du - 1;
+          if (du == k1) vq[vt++] = u;
+        }
+      }
+    }
+    for (size_t i = 0; i < vt; i++) D[vq[i]] = k;
+    removed += vt;
+  }
+  free(dead); free(vq); free(eq);
+}
+
+// ---------------------------------------------------------------- parallel
+#ifdef _OPENMP
+struct alignas(64) Thr {
+  uintE* q;        // owned vertices removed so far (a level's are contiguous)
+  uintE* kl;       // scratch: hyperedges deleted by this owner in a round
+  size_t fhead;    // start of the current frontier in q
+  size_t ftail;    // end of q
+  size_t cnt;      // published: size of the next frontier
+  size_t fdeg;     // published: total degree of the next frontier
+  size_t ainc;     // published: incidences of alive owned hyperedges
+  uintE mn;        // published: min degree of alive owned vertices
+};
+
+// Message buffer written by one thread and read by one owner.
+struct alignas(64) MBuf {
+  uintE* p;
+  size_t len;
+  size_t cap;
+};
+
+static inline void mb_grow(MBuf& b) {
+  b.cap *= 2;
+  b.p = (uintE*)realloc(b.p, sizeof(uintE) * b.cap);
+  if (!b.p) { fprintf(stderr, "Cannot allocate space\n"); exit(1); }
+}
+
+static void peel_par(size_t nv, size_t nh, const CSR& Vc, const CSR& Hc, uintE* D, int TM) {
+  const uintE* vadj = Vc.adj; const uintT* voff = Vc.off;
+  const uintE* hadj = Hc.adj; const uintT* hoff = Hc.off;
+  const size_t nvb = (nv + 63) / 64, nhb = (nh + 63) / 64;
+  const size_t mh = hoff[nh];
+  // S decrement buckets per owner; NBM buckets per sender in total.
+  int S = (int)std::max<size_t>(1, (nv / TM + HKC_BUCKET_V - 1) / HKC_BUCKET_V);
+  S = std::max(1, std::min(S, 256 / TM));
+  const int NBM = TM * S;
+  unsigned char* vbk = (unsigned char*)xmalloc(nvb + 1);   // 64-vertex block -> bucket
+  unsigned char* hown = (unsigned char*)xmalloc(nhb + 1);  // 64-hyperedge block -> owner
+  size_t* vb = (size_t*)xmalloc(sizeof(size_t) * (TM + 1));
+  size_t* hb = (size_t*)xmalloc(sizeof(size_t) * (TM + 1));
+  uint64_t* dead = (uint64_t*)xcalloc(nhb + 1, 8);   // deleted hyperedges
+  uint64_t* kbit = (uint64_t*)xcalloc(nhb + 1, 8);   // deletion requested this round
+  uint64_t* qd = (uint64_t*)xcalloc(nvb + 1, 8);     // vertices removed at this level
+  uint64_t* fbit = (uint64_t*)xcalloc(nvb + 1, 8);   // current frontier
+  Thr* th = (Thr*)aligned_alloc(64, sizeof(Thr) * TM);
+  MBuf* dm = (MBuf*)aligned_alloc(64, sizeof(MBuf) * TM * NBM);  // decrements [src][bucket]
+  MBuf* km = (MBuf*)aligned_alloc(64, sizeof(MBuf) * TM * TM);   // deletion requests [src][dst]
+  if (!th || !dm || !km) { fprintf(stderr, "Cannot allocate space\n"); exit(1); }
+  const size_t dcap0 = mh / ((size_t)TM * NBM) / 2 + 4096;
+  const size_t kcap0 = nh / ((size_t)TM * TM) / 2 + 1024;
+  for (int i = 0; i < TM * NBM; i++) {
+    dm[i].p = (uintE*)xmalloc(sizeof(uintE) * dcap0); dm[i].cap = dcap0; dm[i].len = 0;
+  }
+  for (int i = 0; i < TM * TM; i++) {
+    km[i].p = (uintE*)xmalloc(sizeof(uintE) * kcap0); km[i].cap = kcap0; km[i].len = 0;
+  }
+  // Per-thread queues are slices of these: one entry per owned vertex (plus
+  // one spare slot for the branch-free append) or owned hyperedge.
+  uintE* qall = (uintE*)xmalloc(sizeof(uintE) * (nv + TM + 1));
+  uintE* klall = (uintE*)xmalloc(sizeof(uintE) * (nh + 1));
+  int Tsh = 0;
+#pragma omp parallel num_threads(TM)
+  {
+    const int t = omp_get_thread_num();
+#pragma omp single
+    {
+      // partition by the actual team size
+      const int T = omp_get_num_threads();
+      Tsh = T;
+      for (int s = 0; s <= T; s++) {
+        vb[s] = std::min(nv, ((nvb * s) / T) * 64);
+        hb[s] = std::min(nh, ((nhb * s) / T) * 64);
+      }
+      for (int s = 0; s < T; s++) {
+        size_t b0 = vb[s] / 64, b1 = std::min((vb[s + 1] + 63) / 64, nvb);
+        for (size_t b = b0; b < b1; b++) vbk[b] = (unsigned char)(s * S + ((b - b0) * S) / (b1 - b0));
+        for (size_t b = hb[s] / 64; b < (hb[s + 1] + 63) / 64 && b < nhb; b++) hown[b] = (unsigned char)s;
+      }
+    }  // implicit barrier
+    const int T = Tsh;
+    const int NB = T * S;
+    Thr& me = th[t];
+    const size_t v0 = vb[t], v1 = vb[t + 1], h0 = hb[t], h1 = hb[t + 1];
+    me.q = qall + v0 + t;
+    me.kl = klall + h0;
+    me.fhead = me.ftail = 0;
+    MBuf* mydm = dm + (size_t)t * NBM;   // outgoing decrements, by bucket
+    MBuf* mykm = km + (size_t)t * TM;    // outgoing deletion requests, by owner
+    uintE* kl = me.kl;
+    size_t ainc = hoff[h1] - hoff[h0];
+
+    // Outgoing decrements use local write cursors.  Free space is checked once
+    // per hyperedge, so emitting its members is branch-free.
+    uintE* wp[256];
+    uintE* wend[256];
+    size_t room = 0;   // lower bound on free slots in every outgoing bucket
+    auto dm_begin = [&]() {
+      size_t r = ~(size_t)0;
+      for (int d = 0; d < NB; d++) {
+        wp[d] = mydm[d].p; wend[d] = mydm[d].p + mydm[d].cap;
+        r = std::min(r, mydm[d].cap);
+      }
+      room = r;
+    };
+    auto dm_reserve = [&](size_t need) {
+      size_t r = ~(size_t)0;
+      for (int d = 0; d < NB; d++) {
+        size_t used = wp[d] - mydm[d].p;
+        if ((size_t)(wend[d] - wp[d]) < need) {
+          while (mydm[d].cap - used < need) mb_grow(mydm[d]);
+          wp[d] = mydm[d].p + used; wend[d] = mydm[d].p + mydm[d].cap;
+        }
+        r = std::min(r, (size_t)(wend[d] - wp[d]));
+      }
+      room = r;
+    };
+    auto dm_end = [&]() {
+      for (int d = 0; d < NB; d++) mydm[d].len = wp[d] - mydm[d].p;
+    };
+    // one decrement per member of a deleted hyperedge not removed at this level
+    auto emit_members = [&](const uintE* hs, const uintE* hend) {
+      size_t c = hend - hs;
+      if (room < c) dm_reserve(c);
+      room -= c;
+      for (const uintE* h = hs; h < hend; h++) {
+        uintE u = *h;
+        unsigned o = vbk[u >> 6];
+        uintE* w = wp[o];
+        *w = u;
+        wp[o] = w + (1 - ((qd[u >> 6] >> (u & 63)) & 1));
+      }
+    };
+
+    uintE k = 0;
+    bool first = true;
+    while (true) {
+      // ---- next level: k = min alive degree; collect owned vertices at the local min
+      uintE mn = UINT_E_MAX;
+      const size_t qstart = me.ftail;
+      size_t fdeg = 0;
+      for (size_t v = v0; v < v1; v++) {
+        uintE d = D[v];
+        if (!first && d <= k) continue;
+        if (d < mn) { mn = d; me.ftail = qstart; fdeg = 0; }
+        if (d == mn) { me.q[me.ftail++] = (uintE)v; fdeg += voff[v + 1] - voff[v]; }
+      }
+      me.mn = mn;
+#pragma omp barrier
+      uintE gmn = UINT_E_MAX;
+      for (int s = 0; s < T; s++) gmn = std::min(gmn, th[s].mn);
+      if (gmn == UINT_E_MAX) break;
+      k = gmn; first = false;
+      const uintE k1 = k + 1;
+      if (mn != k) { me.ftail = qstart; fdeg = 0; }
+      for (size_t i = qstart; i < me.ftail; i++) {
+        uintE v = me.q[i];
+        qd[v >> 6] |= 1ULL << (v & 63);
+        fbit[v >> 6] |= 1ULL << (v & 63);
+      }
+      me.fdeg = fdeg; me.ainc = ainc;
+#pragma omp barrier
+      // ---- rounds within level k
+      while (true) {
+        size_t sdeg = 0, sinc = 0;
+        for (int s = 0; s < T; s++) { sdeg += th[s].fdeg; sinc += th[s].ainc; }
+        const bool dense = (double)sinc < HKC_DENSE_RATIO * (double)sdeg;
+        dm_begin();
+        if (!dense) {
+          // phase 1: frontier vertices (in id order) request deletion of
+          // their alive hyperedges
+          for (int d = 0; d < T; d++) mykm[d].len = 0;
+          const size_t fe = me.ftail;
+          size_t j = me.fhead;
+          for (size_t wb = v0 / 64; wb * 64 < v1; wb++) {
+            uint64_t w = fbit[wb];
+            if (!w) continue;
+            fbit[wb] = 0;
+            do { me.q[j++] = (uintE)(wb * 64 + __builtin_ctzll(w)); w &= w - 1; } while (w);
+          }
+          for (size_t i = me.fhead; i < fe; i++) {
+            if (i + 2 * HKC_PF < fe) __builtin_prefetch(voff + me.q[i + 2 * HKC_PF]);
+            if (i + HKC_PF < fe) __builtin_prefetch(vadj + voff[me.q[i + HKC_PF]]);
+            uintE v = me.q[i];
+            const uintE* ve = vadj + voff[v];
+            const uintE* vend = vadj + voff[v + 1];
+            for (; ve < vend; ve++) {
+              uintE e = *ve;
+              if (dead[e >> 6] & (1ULL << (e & 63))) continue;
+              MBuf& b = mykm[hown[e >> 6]];
+              if (b.len == b.cap) mb_grow(b);
+              b.p[b.len++] = e;
+            }
+          }
+          me.fhead = fe;
+#pragma omp barrier
+          // phase 2: owners delete the requested hyperedges in id order
+          for (int s = 0; s < T; s++) {
+            const MBuf& b = km[(size_t)s * TM + t];
+            for (size_t i = 0; i < b.len; i++) {
+              uintE e = b.p[i];
+              kbit[e >> 6] |= 1ULL << (e & 63);
+            }
+          }
+          size_t nk = 0;
+          for (size_t wb = h0 / 64; wb * 64 < h1; wb++) {
+            uint64_t w = kbit[wb] & ~dead[wb];
+            if (!w) continue;
+            kbit[wb] = 0;
+            dead[wb] |= w;
+            do { kl[nk++] = (uintE)(wb * 64 + __builtin_ctzll(w)); w &= w - 1; } while (w);
+          }
+          for (size_t i = 0; i < nk; i++) {
+            if (i + 2 * HKC_PF < nk) __builtin_prefetch(hoff + kl[i + 2 * HKC_PF]);
+            if (i + HKC_PF < nk) __builtin_prefetch(hadj + hoff[kl[i + HKC_PF]]);
+            uintE e = kl[i];
+            const uintE* hs = hadj + hoff[e];
+            const uintE* hend = hadj + hoff[e + 1];
+            ainc -= hend - hs;
+            emit_members(hs, hend);
+          }
+        } else {
+          // dense: every owned alive hyperedge with a removed member is deleted
+          for (size_t i = me.fhead; i < me.ftail; i++) { uintE v = me.q[i]; fbit[v >> 6] = 0; }
+          me.fhead = me.ftail;
+          for (size_t wb = h0 / 64; wb * 64 < h1; wb++) {
+            uint64_t alive = ~dead[wb];
+            if (!alive) continue;
+            uint64_t killed = 0;
+            while (alive) {
+              size_t e = wb * 64 + __builtin_ctzll(alive);
+              alive &= alive - 1;
+              if (e >= h1) break;
+              const uintE* hs = hadj + hoff[e];
+              const uintE* hend = hadj + hoff[e + 1];
+              uint64_t anyq = 0;
+              for (const uintE* h = hs; h < hend; h++) { uintE u = *h; anyq |= qd[u >> 6] >> (u & 63); }
+              if (!(anyq & 1)) continue;
+              killed |= 1ULL << (e & 63);
+              ainc -= hend - hs;
+              emit_members(hs, hend);
+            }
+            dead[wb] |= killed;
+          }
+        }
+        dm_end();
+#pragma omp barrier
+        // phase 3: owners apply decrements bucket by bucket; vertices whose
+        // degree reaches k form the next frontier
+        const size_t fstart = me.ftail;
+        uintE* q = me.q;
+        size_t ft = fstart;
+        for (int j = t * S; j < (t + 1) * S; j++) {
+          for (int s = 0; s < T; s++) {
+            const MBuf& b = dm[(size_t)s * NBM + j];
+            const uintE* buf = b.p;
+            const size_t len = b.len;
+            for (size_t i = 0; i < len; i++) {
+              uintE u = buf[i];
+              uintE du = D[u];
+              D[u] = du - (du > k);
+              q[ft] = u;
+              ft += (du == k1);
+            }
+          }
+        }
+        size_t nfdeg = 0;
+        for (size_t i = fstart; i < ft; i++) {
+          uintE u = q[i];
+          qd[u >> 6] |= 1ULL << (u & 63);
+          fbit[u >> 6] |= 1ULL << (u & 63);
+          nfdeg += voff[u + 1] - voff[u];
+        }
+        me.ftail = ft;
+        me.cnt = ft - me.fhead;
+        me.fdeg = nfdeg; me.ainc = ainc;
+#pragma omp barrier
+        size_t tot = 0;
+        for (int s = 0; s < T; s++) tot += th[s].cnt;
+        if (tot == 0) break;
+      }
+      // level done: removed vertices get core number k
+      for (size_t i = qstart; i < me.ftail; i++) D[me.q[i]] = k;
+    }
+  }
+  for (int i = 0; i < TM * NBM; i++) free(dm[i].p);
+  for (int i = 0; i < TM * TM; i++) free(km[i].p);
+  free(qall); free(klall);
+  free(dm); free(km); free(th); free(qd); free(fbit); free(dead); free(kbit);
+  free(vbk); free(hown); free(vb); free(hb);
+}
+#endif
+
+// D holds initial degrees on entry and core numbers on exit.
+static void peel(size_t nv, size_t nh, const CSR& Vc, const CSR& Hc, uintE* D) {
+  if (nv == 0) return;
+#ifdef _OPENMP
+  int T = omp_get_max_threads();
+  if (T > 64) T = 64;
+  if (T < 1) T = 1;
+  size_t work = nv + (size_t)Vc.off[nv] + (size_t)Hc.off[nh];
+  if (work >= HKC_PAR_MIN) { peel_par(nv, nh, Vc, Hc, D, T); return; }
+#endif
+  peel_seq(nv, nh, Vc, Hc, D);
+}
+
+// Uncompressed vertices: use the loader's arrays in place when the lists are
+// laid out contiguously in id order (as readHypergraph produces); otherwise copy.
+template <class vertex>
+static void build_csr_direct(vertex* X, size_t n, CSR& C) {
+  C.owned = NULL;
+  C.off = (uintT*)xmalloc(sizeof(uintT) * (n + 1));
+  if (n == 0) { C.adj = NULL; C.off[0] = 0; return; }
+  const uintE* base = X[0].getOutNeighbors();
+  bool ok = true;
+  {parallel_for (size_t i = 0; i < n; i++) {
+    const uintE* p = X[i].getOutNeighbors();
+    C.off[i] = (uintT)(p - base);
+    if (p < base) ok = false;
+  }}
+  C.off[n] = C.off[n - 1] + X[n - 1].getOutDegree();
+  if (ok) {
+    bool ok2 = true;
+    {parallel_for (size_t i = 0; i < n; i++) {
+      if ((size_t)C.off[i] + X[i].getOutDegree() != (size_t)C.off[i + 1]) ok2 = false;
+    }}
+    ok = ok2;
+  }
+  if (ok) { C.adj = base; return; }
+  size_t tot = 0;
+  for (size_t i = 0; i < n; i++) { C.off[i] = (uintT)tot; tot += X[i].getOutDegree(); }
+  C.off[n] = (uintT)tot;
+  C.owned = (uintE*)xmalloc(sizeof(uintE) * (tot + 1));
+  {parallel_for (size_t i = 0; i < n; i++) {
+    const uintE* p = X[i].getOutNeighbors();
+    size_t d = X[i].getOutDegree();
+    for (size_t j = 0; j < d; j++) C.owned[C.off[i] + j] = p[j];
+  }}
+  C.adj = C.owned;
+}
+
+// Other vertex types (e.g. compressed): decode adjacency through countOutNgh.
+template <class vertex>
+static void build_csr_generic(vertex* X, size_t n, CSR& C) {
+  C.off = (uintT*)xmalloc(sizeof(uintT) * (n + 1));
+  size_t tot = 0;
